def test_big_statement_stays_under_gmail_clipping(account_factory, tx_factory):
    a = account_factory()
    for i in range(2000):
        tx_factory(a, date(2026, 8, 1 + i % 28), f"Usage fee batch {i}", Decimal("12.34"))
    _, html, text = build_statement(a, date(2026, 8, 1))
    assert len(html.encode()) < 90 * 1024  # Gmail clips at about 102 KB
    assert "and 1900 more transactions" in html
    assert "Unsubscribe" in html


